<?php require_once '../config/config.php';require_login();verify_csrf();$uid=(int)user()['id'];$rid=(int)$_POST['recipe_id'];$action=$_POST['action']??'';if($action==='favourite'){try{$s=db()->prepare("INSERT INTO favourites(user_id,recipe_id) VALUES(?,?)");$s->execute([$uid,$rid]);flash('success','Recipe saved.');}catch(PDOException $e){if(($e->errorInfo[1]??0)===1062){$s=db()->prepare("DELETE FROM favourites WHERE user_id=? AND recipe_id=?");$s->execute([$uid,$rid]);flash('success','Recipe removed from favourites.');}else{flash('danger','Could not update favourite.');}}activity($uid,'favourite',"Recipe #$rid");}elseif($action==='comment'){$c=trim($_POST['comment']??'');if($c){$s=db()->prepare("INSERT INTO recipe_comments(recipe_id,user_id,comment) VALUES(?,?,?)");$s->execute([$rid,$uid,$c]);flash('success','Comment posted.');activity($uid,'comment',"Recipe #$rid");}}header('Location:../pages/recipe.php?id='.$rid);